insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('fe226346-0bbf-4101-a651-fe50edfb52a1', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '1. Pronunciation, Spelling, and the Spanish Sound System', 'This opening unit trains the ear and mouth before habits become difficult to change. Students learn that Spanish spelling is more predictable than English, but still requires attention to vowels, stress, accent marks, and regional variation.', 0),
  ('a8d3d125-4d6a-4bfa-bccd-a67716c3d064', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fe226346-0bbf-4101-a651-fe50edfb52a1', 'subtopic'::public.curated_course_node_type, 'Alphabet and sound-symbol correspondence', 'The point is to connect letters to sounds so students can decode new words, spell what they hear, and read aloud with confidence.', 0),
  ('31a314bc-4880-4df7-81e6-56752e855a75', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'a8d3d125-4d6a-4bfa-bccd-a67716c3d064', 'concept'::public.curated_course_node_type, 'Vowel purity: a, e, i, o, u', null, 0),
  ('52eb8e20-a227-486b-8eca-ccb5856e5814', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'a8d3d125-4d6a-4bfa-bccd-a67716c3d064', 'concept'::public.curated_course_node_type, 'Consonants b/v, d, g, h, j, ll/y, ñ, r/rr', null, 1),
  ('cb8a08b3-8614-437c-b557-9d0d172436e5', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'a8d3d125-4d6a-4bfa-bccd-a67716c3d064', 'concept'::public.curated_course_node_type, 'Letter names for spelling aloud', null, 2),
  ('05f2185a-7cf5-4d74-b27a-26ccdcc8075b', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'a8d3d125-4d6a-4bfa-bccd-a67716c3d064', 'concept'::public.curated_course_node_type, 'Sound variation across regions', null, 3),
  ('19dbc7d1-6232-4397-9265-59442ec8f234', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fe226346-0bbf-4101-a651-fe50edfb52a1', 'subtopic'::public.curated_course_node_type, 'Syllables, stress, and written accents', 'Students learn why accent marks are not decorative; they signal stress, distinguish meanings, and shape pronunciation.', 1),
  ('d1fddc5f-0367-42b6-9710-c37c3b9a791d', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '19dbc7d1-6232-4397-9265-59442ec8f234', 'concept'::public.curated_course_node_type, 'Natural stress rules', null, 0),
  ('5bb31e67-e96d-45de-a6d9-18c9f76bd3ad', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '19dbc7d1-6232-4397-9265-59442ec8f234', 'concept'::public.curated_course_node_type, 'Acute accents', null, 1),
  ('b58a06dc-3ab5-4986-b0d3-058675f471ea', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '19dbc7d1-6232-4397-9265-59442ec8f234', 'concept'::public.curated_course_node_type, 'Question/exclamation marks', null, 2),
  ('29d1320f-674f-4c09-930f-50d2f63e5ba0', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '19dbc7d1-6232-4397-9265-59442ec8f234', 'concept'::public.curated_course_node_type, 'Minimal pairs and meaning contrasts', null, 3),
  ('02759c89-ebe6-4d47-8d2a-75b439ea25dd', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fe226346-0bbf-4101-a651-fe50edfb52a1', 'subtopic'::public.curated_course_node_type, 'Intonation and rhythm', 'The gist is that Spanish sounds syllable-timed and forward-moving, so learners practice phrase rhythm rather than word-by-word English intonation.', 2),
  ('9e5771c4-60d9-4fa0-b5dc-40d83be0a0ab', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '02759c89-ebe6-4d47-8d2a-75b439ea25dd', 'concept'::public.curated_course_node_type, 'Statement/question intonation', null, 0),
  ('29b7e557-7d47-4bff-8083-d3c8f2646b72', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '02759c89-ebe6-4d47-8d2a-75b439ea25dd', 'concept'::public.curated_course_node_type, 'Linking across words', null, 1),
  ('44d27d45-f7a7-4c11-8aa4-0d0f651e0e02', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '02759c89-ebe6-4d47-8d2a-75b439ea25dd', 'concept'::public.curated_course_node_type, 'Chunking phrases', null, 2),
  ('44ed8bdf-3b4c-43af-84a8-99e32f70dbbc', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '02759c89-ebe6-4d47-8d2a-75b439ea25dd', 'concept'::public.curated_course_node_type, 'Listening for stressed syllables', null, 3),
  ('6482883b-5bcc-4d1f-bc93-dee1a16c5b4a', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '2. Classroom Language, Greetings, and Survival Interaction', 'A beginner course makes Spanish usable immediately. This section gives students the language they need to participate in class, ask for help, greet people, and repair communication when they get stuck.', 1),
  ('50b75994-e53c-4844-a7e3-18cdeeacb36d', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '6482883b-5bcc-4d1f-bc93-dee1a16c5b4a', 'subtopic'::public.curated_course_node_type, 'Greetings, farewells, and introductions', 'Students learn social routines that make first contact possible and lower the anxiety of speaking from day one.', 0),
  ('b414417f-15f6-4d40-8b1e-309fa3f34ca7', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '50b75994-e53c-4844-a7e3-18cdeeacb36d', 'concept'::public.curated_course_node_type, 'Hola, buenos días, buenas tardes', null, 0),
  ('4658c672-d9cf-4b1f-abc9-e7d160cc370a', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '50b75994-e53c-4844-a7e3-18cdeeacb36d', 'concept'::public.curated_course_node_type, 'Me llamo..., soy de...', null, 1),
  ('f3a3c1c5-928b-4000-b52e-9741af74f038', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '50b75994-e53c-4844-a7e3-18cdeeacb36d', 'concept'::public.curated_course_node_type, 'Mucho gusto and encantado/a', null, 2),
  ('db6cd877-33ce-4a3a-82b4-e417f7f9feb7', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '50b75994-e53c-4844-a7e3-18cdeeacb36d', 'concept'::public.curated_course_node_type, 'Formal and informal address', null, 3),
  ('a476bc20-bee6-4e55-a005-086eafd27202', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '6482883b-5bcc-4d1f-bc93-dee1a16c5b4a', 'subtopic'::public.curated_course_node_type, 'Classroom survival phrases', 'The point is functional independence: learners can ask for repetition, clarification, permission, and vocabulary without switching entirely to English.', 1),
  ('5421f2ba-8e29-4303-b92b-00e50de6ef9f', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'a476bc20-bee6-4e55-a005-086eafd27202', 'concept'::public.curated_course_node_type, '¿Cómo se dice...?', null, 0),
  ('741ff67a-12b5-46c3-a3db-e958a167e5f2', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'a476bc20-bee6-4e55-a005-086eafd27202', 'concept'::public.curated_course_node_type, 'No entiendo', null, 1),
  ('619c9708-3d13-4a80-a9c7-01d7f7c9dde3', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'a476bc20-bee6-4e55-a005-086eafd27202', 'concept'::public.curated_course_node_type, 'Repita, por favor', null, 2),
  ('69b8d29e-0dfa-4ece-9325-1088fb27d750', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'a476bc20-bee6-4e55-a005-086eafd27202', 'concept'::public.curated_course_node_type, '¿Qué significa...?', null, 3),
  ('0c99b845-0736-4f00-9870-cf950e824433', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '6482883b-5bcc-4d1f-bc93-dee1a16c5b4a', 'subtopic'::public.curated_course_node_type, 'Politeness and repair strategies', 'Students learn that communication includes managing breakdowns gracefully, not producing perfect sentences.', 2),
  ('1e84ad58-7353-4c02-8f3f-f6034c32f573', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '0c99b845-0736-4f00-9870-cf950e824433', 'concept'::public.curated_course_node_type, 'Por favor and gracias', null, 0),
  ('28830f97-3268-4f12-853e-5fc537823641', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '0c99b845-0736-4f00-9870-cf950e824433', 'concept'::public.curated_course_node_type, 'Perdón and disculpe', null, 1),
  ('f7d55045-30a6-48ae-878f-e5a7da1c57f0', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '0c99b845-0736-4f00-9870-cf950e824433', 'concept'::public.curated_course_node_type, 'Slower speech requests', null, 2),
  ('f9d01063-11b7-4bc6-8814-50cc09e5aba5', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '0c99b845-0736-4f00-9870-cf950e824433', 'concept'::public.curated_course_node_type, 'Gesture and circumlocution', null, 3),
  ('cbcc91f1-75c1-4a73-ac88-8f1d44c729ae', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '3. Subject Pronouns and Present-Tense Regular Verbs', 'This unit gives students a productive engine for saying what people do. It also introduces a key difference from English: Spanish verb endings often identify the subject without an explicit pronoun.', 2),
  ('81ec4caa-d656-4fca-97d8-84575977d222', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'cbcc91f1-75c1-4a73-ac88-8f1d44c729ae', 'subtopic'::public.curated_course_node_type, 'Subject pronouns and person/number', 'Students learn pronouns as a map for conjugation, while also seeing why Spanish often drops them.', 0),
  ('f225295d-60b5-4c49-9536-8078ecaf5db7', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '81ec4caa-d656-4fca-97d8-84575977d222', 'concept'::public.curated_course_node_type, 'yo, tú, usted', null, 0),
  ('0523a1b7-8911-4ec3-917c-3af20435452d', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '81ec4caa-d656-4fca-97d8-84575977d222', 'concept'::public.curated_course_node_type, 'él, ella', null, 1),
  ('9bdfe138-bf2c-4d82-b0f5-7a33343ffc0e', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '81ec4caa-d656-4fca-97d8-84575977d222', 'concept'::public.curated_course_node_type, 'nosotros/as', null, 2),
  ('79cbdf90-03aa-4d22-8c41-46118badbbe5', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '81ec4caa-d656-4fca-97d8-84575977d222', 'concept'::public.curated_course_node_type, 'ellos/as, ustedes', null, 3),
  ('7f0b7c20-57b5-407a-93f5-86fd23d59044', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'cbcc91f1-75c1-4a73-ac88-8f1d44c729ae', 'subtopic'::public.curated_course_node_type, 'Regular -ar verbs', 'The first regular pattern lets students speak about common routines with high payoff.', 1),
  ('1ac55bee-c243-4a4a-87cf-0fa62a9d2acf', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7f0b7c20-57b5-407a-93f5-86fd23d59044', 'concept'::public.curated_course_node_type, 'hablar, estudiar, trabajar', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('5e865f14-a1f4-4f22-a936-ba27a39de7f2', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7f0b7c20-57b5-407a-93f5-86fd23d59044', 'concept'::public.curated_course_node_type, 'stem plus endings', null, 1),
  ('7aa77cda-7851-40db-83ae-a354c36c9675', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7f0b7c20-57b5-407a-93f5-86fd23d59044', 'concept'::public.curated_course_node_type, 'yo form and agreement', null, 2),
  ('b8fe6055-db6e-4bc6-adc5-0f6f3a661701', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7f0b7c20-57b5-407a-93f5-86fd23d59044', 'concept'::public.curated_course_node_type, 'frequency expressions', null, 3),
  ('abfd8dbd-65d0-4a89-a372-9cade42097a3', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'cbcc91f1-75c1-4a73-ac88-8f1d44c729ae', 'subtopic'::public.curated_course_node_type, 'Regular -er and -ir verbs', 'Students extend the same logic to more verb families, noticing similarities and differences across patterns.', 2),
  ('8c532da7-8f3c-42b8-99ef-c4f113cefa66', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'abfd8dbd-65d0-4a89-a372-9cade42097a3', 'concept'::public.curated_course_node_type, 'comer, beber, leer', null, 0),
  ('10fb4956-7f8c-4ab0-a3b0-2d565e420311', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'abfd8dbd-65d0-4a89-a372-9cade42097a3', 'concept'::public.curated_course_node_type, 'vivir, escribir, asistir', null, 1),
  ('6c06f7f6-e4d1-4324-b833-5ac407abed3a', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'abfd8dbd-65d0-4a89-a372-9cade42097a3', 'concept'::public.curated_course_node_type, 'negative forms', null, 2),
  ('9dfb86fd-3c01-470f-8e12-1ba93609c96b', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'abfd8dbd-65d0-4a89-a372-9cade42097a3', 'concept'::public.curated_course_node_type, 'habitual present meaning', null, 3),
  ('9d667517-fccf-4571-8416-38aaccd6b914', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '4. Gender, Number, Articles, and Noun-Adjective Agreement', 'Spanish meaning depends on agreement. This section trains students to hear and produce the small endings that make nouns, articles, and adjectives work together.', 3),
  ('fcfc0f1e-21e9-427e-adce-333824801474', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9d667517-fccf-4571-8416-38aaccd6b914', 'subtopic'::public.curated_course_node_type, 'Grammatical gender', 'Students learn gender as a property of nouns, not a statement about real-world identity, and begin recognizing common patterns and exceptions.', 0),
  ('ee9a621a-0fc7-4bbd-8a8e-1f38faabb2d1', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fcfc0f1e-21e9-427e-adce-333824801474', 'concept'::public.curated_course_node_type, 'masculine -o patterns', null, 0),
  ('8cc7a839-fe74-4f83-9df0-4064237d924c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fcfc0f1e-21e9-427e-adce-333824801474', 'concept'::public.curated_course_node_type, 'feminine -a patterns', null, 1),
  ('c5119498-8d0d-4c5d-b99b-b5417b976ea4', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fcfc0f1e-21e9-427e-adce-333824801474', 'concept'::public.curated_course_node_type, 'common exceptions', null, 2),
  ('6491d7e7-1e00-48f2-984b-3d34aca34a53', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fcfc0f1e-21e9-427e-adce-333824801474', 'concept'::public.curated_course_node_type, 'people nouns and inclusive awareness', null, 3),
  ('e2caa400-04b0-473b-8952-c70dc9b2ea15', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9d667517-fccf-4571-8416-38aaccd6b914', 'subtopic'::public.curated_course_node_type, 'Singular and plural formation', 'The goal is to make quantity visible and audible through articles, nouns, adjectives, and verbs.', 1),
  ('74fc40ac-fcf7-4f88-8f07-5aac78a34dbe', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'e2caa400-04b0-473b-8952-c70dc9b2ea15', 'concept'::public.curated_course_node_type, 'adding -s or -es', null, 0),
  ('9e5442a5-7dac-4829-82ae-70003905ddde', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'e2caa400-04b0-473b-8952-c70dc9b2ea15', 'concept'::public.curated_course_node_type, 'words ending in consonants', null, 1),
  ('74599c56-19b5-4855-9eaa-d3fba6e74772', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'e2caa400-04b0-473b-8952-c70dc9b2ea15', 'concept'::public.curated_course_node_type, 'plural articles', null, 2),
  ('9cc6f24f-a21c-4192-abc0-06e3df70679c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'e2caa400-04b0-473b-8952-c70dc9b2ea15', 'concept'::public.curated_course_node_type, 'agreement across a phrase', null, 3),
  ('f59b6dbb-38ee-433d-b2c9-48eeb3931765', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9d667517-fccf-4571-8416-38aaccd6b914', 'subtopic'::public.curated_course_node_type, 'Articles and adjective placement', 'Students learn how definite and indefinite articles shape meaning and how adjectives normally follow nouns in Spanish.', 2),
  ('c19c4a73-9576-4e49-b3f7-9208f09e9cd3', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'f59b6dbb-38ee-433d-b2c9-48eeb3931765', 'concept'::public.curated_course_node_type, 'el, la, los, las', null, 0),
  ('807477e5-38e2-40d2-8869-466548f98d70', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'f59b6dbb-38ee-433d-b2c9-48eeb3931765', 'concept'::public.curated_course_node_type, 'un, una, unos, unas', null, 1),
  ('2808ea12-46b7-41db-9f6b-92ec43259d07', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'f59b6dbb-38ee-433d-b2c9-48eeb3931765', 'concept'::public.curated_course_node_type, 'descriptive adjectives', null, 2),
  ('406278d7-0922-45e1-a523-3afaab1f6880', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'f59b6dbb-38ee-433d-b2c9-48eeb3931765', 'concept'::public.curated_course_node_type, 'meaning-changing adjective position', null, 3),
  ('1499b78b-77b8-49f7-baf2-725e658cdd6f', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '5. Ser, Estar, Hay, Tener, and Ir', 'These high-frequency verbs let beginners say much more than regular verb patterns alone. Students use them to identify, locate, describe states, express possession, talk about obligations, and make near-future plans.', 4),
  ('2e594d2d-86e6-46a1-baaa-1cc0e446f83a', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '1499b78b-77b8-49f7-baf2-725e658cdd6f', 'subtopic'::public.curated_course_node_type, 'Ser for identity and inherent description', 'Students use ser for names, origins, professions, personality, time, and stable descriptions.', 0),
  ('cf93b81a-daec-44cd-be83-0983fcfcb138', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '2e594d2d-86e6-46a1-baaa-1cc0e446f83a', 'concept'::public.curated_course_node_type, 'soy, eres, es', null, 0),
  ('f25ea136-bd04-42e0-a1d6-9133d6b5c849', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '2e594d2d-86e6-46a1-baaa-1cc0e446f83a', 'concept'::public.curated_course_node_type, 'origin with de', null, 1),
  ('cef7f9ee-96a6-41f7-9982-59cbe509cf94', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '2e594d2d-86e6-46a1-baaa-1cc0e446f83a', 'concept'::public.curated_course_node_type, 'time and date', null, 2),
