  ('69db7eb5-0c45-40dc-af69-42392e25942c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '2b78fc21-1fc4-4680-b9c1-621eceb3508b', 'concept'::public.curated_course_node_type, 'estoy, estás, está', null, 0),
  ('1ee70432-ecf3-47c8-9193-7716eacd0760', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '2b78fc21-1fc4-4680-b9c1-621eceb3508b', 'concept'::public.curated_course_node_type, 'location with prepositions', null, 1),
