  ('80c2e9b4-3757-42dc-b948-8e5aa73f67bc', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '2b78fc21-1fc4-4680-b9c1-621eceb3508b', 'concept'::public.curated_course_node_type, 'temporary conditions', null, 3),
  ('fd5fa559-08fa-4cda-b595-5bfbd74847f5', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '1499b78b-77b8-49f7-baf2-725e658cdd6f', 'subtopic'::public.curated_course_node_type, 'Tener, tener que, ir, and ir a + infinitive', 'These verbs unlock practical beginner communication about age, possession, obligations, destinations, and immediate plans.', 2),
  ('1c7e9d60-08f7-413a-a692-b74ef449a26b', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fd5fa559-08fa-4cda-b595-5bfbd74847f5', 'concept'::public.curated_course_node_type, 'tener expressions', null, 0),
  ('7947df62-6799-49fe-b811-33c166da8608', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fd5fa559-08fa-4cda-b595-5bfbd74847f5', 'concept'::public.curated_course_node_type, 'age and possession', null, 1),
  ('f9400c78-25ca-40f7-ac25-c5d82b526326', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fd5fa559-08fa-4cda-b595-5bfbd74847f5', 'concept'::public.curated_course_node_type, 'ir + a + place', null, 2),
