insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('cfd327b6-9521-487d-9051-a7a579516ab9', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '6. Basic Questions, Negation, and Word Order', 'Conversation depends on asking, answering, and clarifying. This section teaches students how Spanish forms questions and negatives, and how word order shifts with communicative purpose.', 5),
  ('6b1b10e5-1776-431b-b2be-4d4855b2a61c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'cfd327b6-9521-487d-9051-a7a579516ab9', 'subtopic'::public.curated_course_node_type, 'Yes/no questions', 'Students learn that intonation and punctuation can signal a question even when the word order looks familiar.', 0),
  ('3f0e35ed-bfc1-4fc1-b536-69d04377851b', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '6b1b10e5-1776-431b-b2be-4d4855b2a61c', 'concept'::public.curated_course_node_type, 'inverted question marks', null, 0),
