  ('297f0ee9-3256-4811-a4b8-c77d4c1581cf', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '6b1b10e5-1776-431b-b2be-4d4855b2a61c', 'concept'::public.curated_course_node_type, 'subject placement', null, 2),
  ('12e1410a-e653-4303-845e-a7f4a2323daf', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '6b1b10e5-1776-431b-b2be-4d4855b2a61c', 'concept'::public.curated_course_node_type, 'tag-style follow-up questions', null, 3),
  ('fd91889e-9378-4533-b56a-594261cd5b59', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'cfd327b6-9521-487d-9051-a7a579516ab9', 'subtopic'::public.curated_course_node_type, 'Question words', 'The goal is to gather real information: who, what, when, where, why, how, and how much.', 1),
  ('98c7f02a-8afe-409a-bc4f-34b9adc1e3bb', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fd91889e-9378-4533-b56a-594261cd5b59', 'concept'::public.curated_course_node_type, 'qué, quién, cuándo', null, 0),
  ('f3dded97-3017-4194-bb44-3888be1c1017', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fd91889e-9378-4533-b56a-594261cd5b59', 'concept'::public.curated_course_node_type, 'dónde, de dónde, adónde', null, 1),
  ('b1e9acfd-7a02-4b0c-aa05-d221d88e3261', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fd91889e-9378-4533-b56a-594261cd5b59', 'concept'::public.curated_course_node_type, 'por qué and porque', null, 2),
  ('dcda35eb-16d4-4642-8fad-16110a648f2c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fd91889e-9378-4533-b56a-594261cd5b59', 'concept'::public.curated_course_node_type, 'cuánto/a/os/as', null, 3),
  ('3ee15cea-bf37-49a7-973d-a14314b80dbe', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'cfd327b6-9521-487d-9051-a7a579516ab9', 'subtopic'::public.curated_course_node_type, 'Negation and sentence rhythm', 'Students learn to make accurate negative statements and avoid English-based word order habits.', 2),
  ('268aae23-63b0-4157-a786-1689b38afd3e', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '3ee15cea-bf37-49a7-973d-a14314b80dbe', 'concept'::public.curated_course_node_type, 'no before the verb', null, 0),
  ('47274fdf-f037-4c38-93bc-af003c46f50d', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '3ee15cea-bf37-49a7-973d-a14314b80dbe', 'concept'::public.curated_course_node_type, 'nunca and tampoco', null, 1),
  ('5fb1a131-b5d5-46ea-a1ea-c36086cb9c2e', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '3ee15cea-bf37-49a7-973d-a14314b80dbe', 'concept'::public.curated_course_node_type, 'negative answers', null, 2),
  ('e5d6594c-d09f-4909-99c0-60ee541bbab9', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '3ee15cea-bf37-49a7-973d-a14314b80dbe', 'concept'::public.curated_course_node_type, 'word order in simple statements', null, 3),
  ('21c58f75-f6be-4875-bbd2-ec4312aa21ea', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '7. Everyday Vocabulary, Descriptions, Preferences, and Possession', 'Vocabulary becomes durable when it is attached to personal meaning. This unit helps students describe their world: people, courses, family, places, likes, belongings, and daily activities.', 6),
  ('7a053912-bf03-457f-9f21-df350a62f8f6', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '21c58f75-f6be-4875-bbd2-ec4312aa21ea', 'subtopic'::public.curated_course_node_type, 'People, family, and communities', 'Students learn to describe relationships in culturally aware ways while practicing agreement and possession.', 0),
  ('4034e865-f6f6-40f9-af21-fa4af8f76e8e', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7a053912-bf03-457f-9f21-df350a62f8f6', 'concept'::public.curated_course_node_type, 'family vocabulary', null, 0),
  ('ef896cc3-ca1f-4a5f-8233-0cecded621ac', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7a053912-bf03-457f-9f21-df350a62f8f6', 'concept'::public.curated_course_node_type, 'chosen community language', null, 1),
  ('00e3ff7f-2f10-4a06-9de7-7d9546308d80', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7a053912-bf03-457f-9f21-df350a62f8f6', 'concept'::public.curated_course_node_type, 'physical and personality adjectives', null, 2),
  ('273e8e1c-3038-437f-935f-2be41a9b9481', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7a053912-bf03-457f-9f21-df350a62f8f6', 'concept'::public.curated_course_node_type, 'possessive adjectives', null, 3),
  ('c12722c2-6999-45ed-9002-c512d9843a12', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '21c58f75-f6be-4875-bbd2-ec4312aa21ea', 'subtopic'::public.curated_course_node_type, 'Academic and daily-life vocabulary', 'The point is to make Spanish relevant to students'' actual routines and college environment.', 1),
  ('092b0187-730d-4687-8610-757d5d288d24', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'c12722c2-6999-45ed-9002-c512d9843a12', 'concept'::public.curated_course_node_type, 'courses and majors', null, 0),
  ('9a1488e0-985f-4f89-82b8-572e30db122c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'c12722c2-6999-45ed-9002-c512d9843a12', 'concept'::public.curated_course_node_type, 'classroom objects', null, 1),
  ('370acd97-6356-49e0-9fb7-90aa0318f4c9', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'c12722c2-6999-45ed-9002-c512d9843a12', 'concept'::public.curated_course_node_type, 'places on campus', null, 2),
  ('a6a85833-1400-4dea-89bf-dd72a3321832', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'c12722c2-6999-45ed-9002-c512d9843a12', 'concept'::public.curated_course_node_type, 'daily activities', null, 3),
  ('401c9891-642f-4b38-b303-76d3ee573098', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '21c58f75-f6be-4875-bbd2-ec4312aa21ea', 'subtopic'::public.curated_course_node_type, 'Gustar and preferences', 'Students learn a high-frequency structure that works differently from English and is essential for real conversation.', 2),
  ('db88c041-231c-45f6-a3f5-fd0dfec8533b', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '401c9891-642f-4b38-b303-76d3ee573098', 'concept'::public.curated_course_node_type, 'me gusta / me gustan', null, 0),
  ('65d0aee0-2083-4d93-bd79-b00453ca1d6c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '401c9891-642f-4b38-b303-76d3ee573098', 'concept'::public.curated_course_node_type, 'te gusta and le gusta', null, 1),
  ('f94ddfb0-51dc-42e9-a355-73a04efd0274', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '401c9891-642f-4b38-b303-76d3ee573098', 'concept'::public.curated_course_node_type, 'infinitives after gustar', null, 2),
  ('f5962487-4454-4c63-866f-701f700c0195', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '401c9891-642f-4b38-b303-76d3ee573098', 'concept'::public.curated_course_node_type, 'also/neither: también/tampoco', null, 3),
  ('39d3b094-8390-4d47-a1bb-dd2f29877fe0', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '8. Numbers, Time, Calendar, Schedules, and Quantity', 'This section makes Spanish practical for daily logistics. Students use numbers and time expressions to coordinate meetings, talk about ages and dates, read schedules, and handle prices or quantities.', 7),
  ('efcceaf2-dd3d-459d-a63b-ad03981cf71d', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '39d3b094-8390-4d47-a1bb-dd2f29877fe0', 'subtopic'::public.curated_course_node_type, 'Numbers and basic quantities', 'Students learn numbers as communicative tools, not isolated memorization.', 0),
  ('f25566ae-48b2-4df8-b9cc-811e788a9b78', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'efcceaf2-dd3d-459d-a63b-ad03981cf71d', 'concept'::public.curated_course_node_type, '0-100 and beyond', null, 0),
  ('5bcbf0bb-fc67-4665-990d-7eb1acb2912a', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'efcceaf2-dd3d-459d-a63b-ad03981cf71d', 'concept'::public.curated_course_node_type, 'phone numbers', null, 1),
  ('1208a551-196e-433d-9b39-83488b879feb', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'efcceaf2-dd3d-459d-a63b-ad03981cf71d', 'concept'::public.curated_course_node_type, 'prices', null, 2),
  ('57effea0-2a82-4b93-a5a4-6be71411f4ae', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'efcceaf2-dd3d-459d-a63b-ad03981cf71d', 'concept'::public.curated_course_node_type, 'agreement with uno/una', null, 3),
  ('29337658-fc31-472a-bef6-226523bf6d97', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '39d3b094-8390-4d47-a1bb-dd2f29877fe0', 'subtopic'::public.curated_course_node_type, 'Clock time and schedules', 'The point is to talk about when things happen and understand common schedule language.', 1),
  ('fb55af08-5939-4cf7-b16c-36ec86917042', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '29337658-fc31-472a-bef6-226523bf6d97', 'concept'::public.curated_course_node_type, '¿Qué hora es?', null, 0);
