  ('f1f6c712-5c5e-4381-8e8e-5e1835fbe8cb', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9fc7274c-c2df-4f2a-a1dc-df0244293a92', 'concept'::public.curated_course_node_type, 'days and months', null, 0),
