  ('fcceb1e3-0e77-41ad-87e2-a79b89543733', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9fc7274c-c2df-4f2a-a1dc-df0244293a92', 'concept'::public.curated_course_node_type, 'seasons', null, 2),
  ('44bf3faa-893c-4e5f-8ec9-19741a798ce1', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9fc7274c-c2df-4f2a-a1dc-df0244293a92', 'concept'::public.curated_course_node_type, 'class and event planning', null, 3),
  ('695af733-93d0-431e-bddf-21e1c6414947', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '9. Listening, Speaking, and Task-Based Communication', 'Grammar knowledge only matters when students can use it under real-time conditions. This unit turns structures into novice performance through input, interaction, repetition, and purposeful tasks.', 8),
  ('180bbad9-2613-417c-9b25-e04e09238a5c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '695af733-93d0-431e-bddf-21e1c6414947', 'subtopic'::public.curated_course_node_type, 'Comprehensible input', 'Students train listening by using context, visuals, cognates, repetition, and prediction rather than translating every word.', 0),
  ('5ebe1559-9248-4312-9a30-8bf96c5a65fb', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '180bbad9-2613-417c-9b25-e04e09238a5c', 'concept'::public.curated_course_node_type, 'gist listening', null, 0),
  ('0b6028fc-b82d-49ca-9cae-5fe6b8240bbb', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '180bbad9-2613-417c-9b25-e04e09238a5c', 'concept'::public.curated_course_node_type, 'specific-detail listening', null, 1),
  ('f94f7206-d312-4b07-96e2-a310cbb7ac5a', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '180bbad9-2613-417c-9b25-e04e09238a5c', 'concept'::public.curated_course_node_type, 'cognates and context clues', null, 2),
  ('985b9f04-2a88-423e-b324-fa00f3e58f7b', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '180bbad9-2613-417c-9b25-e04e09238a5c', 'concept'::public.curated_course_node_type, 'tolerance for ambiguity', null, 3),
  ('59fc3270-c19e-496f-8418-ed4ebdf66ecd', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '695af733-93d0-431e-bddf-21e1c6414947', 'subtopic'::public.curated_course_node_type, 'Interpersonal speaking tasks', 'The goal is to exchange information with another person, even with limited language.', 1),
  ('13eb3bf1-5631-4158-a811-cd451788637f', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '59fc3270-c19e-496f-8418-ed4ebdf66ecd', 'concept'::public.curated_course_node_type, 'information gaps', null, 0),
