  ('977b53b2-2263-4fb6-9dc5-65ac0ea827dd', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '59fc3270-c19e-496f-8418-ed4ebdf66ecd', 'concept'::public.curated_course_node_type, 'role plays', null, 2),
  ('ed41188c-2e5f-486f-9fa5-ad60ae49a9e1', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '59fc3270-c19e-496f-8418-ed4ebdf66ecd', 'concept'::public.curated_course_node_type, 'follow-up questions', null, 3),
  ('410ac5a7-caa9-46c4-9067-b0b89152828f', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '695af733-93d0-431e-bddf-21e1c6414947', 'subtopic'::public.curated_course_node_type, 'Presentational speaking', 'Students learn to prepare short spoken messages that are accurate, comprehensible, and personally meaningful.', 2),
  ('647682a8-b9c7-44e1-a66a-f2ba2920421f', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '410ac5a7-caa9-46c4-9067-b0b89152828f', 'concept'::public.curated_course_node_type, 'short self-introductions', null, 0),
  ('13d29f9b-9a9d-4a9b-bd18-1e66a1a72b74', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '410ac5a7-caa9-46c4-9067-b0b89152828f', 'concept'::public.curated_course_node_type, 'campus or family descriptions', null, 1),
  ('76001efc-d7a7-46dd-ae81-d7bcb174d7f1', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '410ac5a7-caa9-46c4-9067-b0b89152828f', 'concept'::public.curated_course_node_type, 'preference reports', null, 2),
  ('30de9779-8ad9-4b7a-9036-13aa964214a6', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '410ac5a7-caa9-46c4-9067-b0b89152828f', 'concept'::public.curated_course_node_type, 'pronunciation self-checks', null, 3),
  ('753b64ba-d6c3-473a-9433-38860509ae78', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '10. Short Guided Writing and Sentence-Building', 'Writing gives beginners time to notice accuracy. Students learn to build sentences, combine them into short paragraphs, revise for agreement and verb forms, and use simple connectors.', 9),
  ('4b6d21d1-b795-40ad-96e6-0cccfa3a8362', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '753b64ba-d6c3-473a-9433-38860509ae78', 'subtopic'::public.curated_course_node_type, 'Sentence construction', 'Students practice building complete, accurate sentences before moving into paragraphs.', 0),
  ('d0d6df4a-4378-4267-a8c7-86fa6720f3bc', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '4b6d21d1-b795-40ad-96e6-0cccfa3a8362', 'concept'::public.curated_course_node_type, 'subject-verb agreement', null, 0),
  ('cd22a141-e34a-4c94-b148-9ae73b49a660', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '4b6d21d1-b795-40ad-96e6-0cccfa3a8362', 'concept'::public.curated_course_node_type, 'noun-adjective agreement', null, 1),
  ('297e669f-5f73-483f-823f-f97daf96e528', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '4b6d21d1-b795-40ad-96e6-0cccfa3a8362', 'concept'::public.curated_course_node_type, 'punctuation and accents', null, 2),
  ('a7256692-941d-4d7f-bb84-8a363bd87146', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '4b6d21d1-b795-40ad-96e6-0cccfa3a8362', 'concept'::public.curated_course_node_type, 'basic word order', null, 3),
  ('b51c2395-7529-47ed-962a-aa82b816a95a', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '753b64ba-d6c3-473a-9433-38860509ae78', 'subtopic'::public.curated_course_node_type, 'Paragraph organization', 'The point is to move from isolated sentences to a small coherent message.', 1),
  ('ecbbcf1c-fa46-49f1-9abe-b76a7b93b793', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'b51c2395-7529-47ed-962a-aa82b816a95a', 'concept'::public.curated_course_node_type, 'topic sentence', null, 0),
  ('7160eb3f-b49e-45d1-b126-72c288bdbc33', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'b51c2395-7529-47ed-962a-aa82b816a95a', 'concept'::public.curated_course_node_type, 'supporting details', null, 1),
  ('00dae471-448c-436e-976f-7393d818c6d4', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'b51c2395-7529-47ed-962a-aa82b816a95a', 'concept'::public.curated_course_node_type, 'connectors: y, pero, también, porque', null, 2),
  ('9bfa7a67-f75a-406a-bd0b-63680df7150f', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'b51c2395-7529-47ed-962a-aa82b816a95a', 'concept'::public.curated_course_node_type, 'logical sequence', null, 3),
  ('5bb4efcf-fe50-4b7c-b4db-a3a2c9214216', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '753b64ba-d6c3-473a-9433-38860509ae78', 'subtopic'::public.curated_course_node_type, 'Revision and self-correction', 'Students learn that accuracy improves through habits of checking, not just teacher correction.', 2),
  ('6c1703c1-c07e-4229-98f6-2856fafc1c0d', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '5bb4efcf-fe50-4b7c-b4db-a3a2c9214216', 'concept'::public.curated_course_node_type, 'verb ending check', null, 0),
