insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('8c80748c-223b-4d42-b1c1-e3905075f5f3', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '11. Cultural Introductions and Intercultural Comparison', 'Culture is not an add-on after grammar. Students encounter Spanish as a language used across diverse communities, histories, identities, registers, and daily practices.', 10),
  ('1c3c5dac-16a9-4471-bfb9-4e6e8250fa54', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '8c80748c-223b-4d42-b1c1-e3905075f5f3', 'subtopic'::public.curated_course_node_type, 'Geography and diversity of the Spanish-speaking world', 'Students begin replacing a single-story view of Spanish with a map of varied regions and communities.', 0),
  ('4152371c-b5df-48f1-b412-4846018704ce', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '1c3c5dac-16a9-4471-bfb9-4e6e8250fa54', 'concept'::public.curated_course_node_type, 'Spain and Latin America', null, 0),
  ('54b5025c-7f04-4d11-aa3a-1eff526d3db7', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '1c3c5dac-16a9-4471-bfb9-4e6e8250fa54', 'concept'::public.curated_course_node_type, 'U.S. Spanish-speaking communities', null, 1),
  ('1f8da675-e5d8-4b49-9124-d40a255e40f3', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '1c3c5dac-16a9-4471-bfb9-4e6e8250fa54', 'concept'::public.curated_course_node_type, 'regional vocabulary', null, 2),
  ('eb7bd1b6-d224-4622-986c-e3089789ffa3', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '1c3c5dac-16a9-4471-bfb9-4e6e8250fa54', 'concept'::public.curated_course_node_type, 'language contact', null, 3),
  ('7f023f19-71fc-4dd8-814c-dcc50aadcf73', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '8c80748c-223b-4d42-b1c1-e3905075f5f3', 'subtopic'::public.curated_course_node_type, 'Products, practices, and perspectives', 'The goal is to connect visible cultural items and routines to deeper values and social meanings.', 1),
  ('fcb63d58-14b8-4702-9c60-6a2130a921f7', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7f023f19-71fc-4dd8-814c-dcc50aadcf73', 'concept'::public.curated_course_node_type, 'names and naming practices', null, 0),
  ('e6e327d3-fcb6-4175-8589-a2201551d9e5', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7f023f19-71fc-4dd8-814c-dcc50aadcf73', 'concept'::public.curated_course_node_type, 'mealtimes and greetings', null, 1),
  ('66cea9ad-06f9-4f09-a9af-97109597c156', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7f023f19-71fc-4dd8-814c-dcc50aadcf73', 'concept'::public.curated_course_node_type, 'education and family contexts', null, 2),
  ('9b90f23c-1a41-4dee-b301-e81e2a38cf69', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '7f023f19-71fc-4dd8-814c-dcc50aadcf73', 'concept'::public.curated_course_node_type, 'music, media, and public life', null, 3),
  ('ca228e19-e467-47f8-bca4-ceb20c4d548c', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '8c80748c-223b-4d42-b1c1-e3905075f5f3', 'subtopic'::public.curated_course_node_type, 'Intercultural reflection', 'Students learn to compare without stereotyping and to ask better questions about difference.', 2),
  ('5a73172f-dd8c-4025-aec0-7eec5e970b02', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'ca228e19-e467-47f8-bca4-ceb20c4d548c', 'concept'::public.curated_course_node_type, 'similarities and differences', null, 0),
  ('a01dd2f0-798b-49fc-9755-adf6f4931182', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'ca228e19-e467-47f8-bca4-ceb20c4d548c', 'concept'::public.curated_course_node_type, 'register and politeness', null, 1),
  ('d74fac4a-2cd5-4037-96bd-f35f931791cb', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'ca228e19-e467-47f8-bca4-ceb20c4d548c', 'concept'::public.curated_course_node_type, 'avoidance of overgeneralization', null, 2),
  ('1367d551-b9c9-4443-8145-660f71c63b64', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'ca228e19-e467-47f8-bca4-ceb20c4d548c', 'concept'::public.curated_course_node_type, 'respectful curiosity', null, 3),
  ('70f44b81-d785-4e00-bf1c-0bbf5de66146', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', null, 'topic'::public.curated_course_node_type, '12. Integrated Novice Portfolio and Independent Learning Strategies', 'The final unit consolidates the semester and prepares students for Elementary Spanish II. Students collect evidence of what they can do and learn how to keep improving outside class.', 11),
  ('9d35cc3e-f783-4ef9-847f-2d17a0c30c8e', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '70f44b81-d785-4e00-bf1c-0bbf5de66146', 'subtopic'::public.curated_course_node_type, 'Novice portfolio', 'Students demonstrate growth across speaking, listening, reading, writing, vocabulary, grammar, and culture.', 0),
  ('c82115fc-1afc-45cf-8fdf-442755885fe2', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9d35cc3e-f783-4ef9-847f-2d17a0c30c8e', 'concept'::public.curated_course_node_type, 'oral sample', null, 0),
  ('22ab4709-79d0-41af-af0c-238a98a38ceb', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9d35cc3e-f783-4ef9-847f-2d17a0c30c8e', 'concept'::public.curated_course_node_type, 'revised writing', null, 1),
  ('2d9de134-f931-40c1-88f8-1a9e7a0cbb03', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9d35cc3e-f783-4ef9-847f-2d17a0c30c8e', 'concept'::public.curated_course_node_type, 'listening log', null, 2),
  ('e7502232-4650-4acc-836f-508caea5640e', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '9d35cc3e-f783-4ef9-847f-2d17a0c30c8e', 'concept'::public.curated_course_node_type, 'cultural reflection', null, 3),
  ('fa004109-9a6b-4765-b9f2-ecf3bdf046fb', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '70f44b81-d785-4e00-bf1c-0bbf5de66146', 'subtopic'::public.curated_course_node_type, 'Vocabulary and grammar study strategies', 'The point is to help students study smarter, with retrieval, spaced repetition, and patterns rather than passive rereading.', 1),
  ('29703272-ae21-4059-a6bc-dfd76c0d13f9', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fa004109-9a6b-4765-b9f2-ecf3bdf046fb', 'concept'::public.curated_course_node_type, 'flashcard design', null, 0),
  ('78ddbc49-9baf-4619-b5d8-0e535c62d8b2', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fa004109-9a6b-4765-b9f2-ecf3bdf046fb', 'concept'::public.curated_course_node_type, 'retrieval practice', null, 1),
  ('f187ded2-83a6-41ea-acd0-be66b3191a3d', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', 'fa004109-9a6b-4765-b9f2-ecf3bdf046fb', 'concept'::public.curated_course_node_type, 'verb charts with meaning', null, 2),
