  ('074525c0-e8c4-48ff-bb21-7dbbb2d8ca67', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '70f44b81-d785-4e00-bf1c-0bbf5de66146', 'subtopic'::public.curated_course_node_type, 'Independent input and pronunciation habits', 'Students learn sustainable routines for listening, shadowing, reading, and self-recording.', 2),
  ('ec58879e-06b5-41fd-955e-3ac26998a4c0', 'b0c1d2e3-4f5a-4b85-8c55-6d7e8f9a0b15', '074525c0-e8c4-48ff-bb21-7dbbb2d8ca67', 'concept'::public.curated_course_node_type, 'graded videos', null, 0),
